F_set = set(F_list)
adj = {k:[] for k in F_list}
for k in F_list:
    # Check successor k + 11
    if k + 11 in F_set:
        adj[k].append(k + 11)
    # Check successor k + 20
    if k + 20 in F_set:
        adj[k].append(k + 20)

print("--- Graph Adjacency List (Sample) ---")
# Print sample dependencies for structure verification
for k in F_list[:5]:
    print(f"{k}: {adj[k]}")
print(f"Total nodes in F: {len(F_list)}")

# Verification that K=F is closed
is_F_closed = True
for k in F_list:
    for successor in adj[k]:
        if successor not in F_set: # Should not happen by construction, but good check
            is_F_closed = False
            break
if is_F_closed:
    print("K=F is confirmed closed.")
else:
    print("K=F is NOT closed.")

